const preferences = [
  {key:'format', label:'Format', options:['Plain text','Field report with observations']},
  {key:'sharing', label:'Sharing and review permissions', options:['Only me','Field team and visiting researchers']}
];

export function mountPreferences(root, notebook) {
  root.innerHTML = preferences.map(pref => `<div class="preference-row"><label for="${pref.key}">${pref.label}</label><select id="${pref.key}">${pref.options.map(option => `<option>${option}</option>`).join('')}</select><button class="apply">Apply</button></div>`).join('');
  const render = () => {
    for (const pref of preferences) {
      root.querySelector('#' + pref.key).value = notebook.current.preferences[pref.key];
      root.querySelector('#' + pref.key).closest('.preference-row').querySelector('.apply').textContent = 'Apply';
    }
  };
  for (const pref of preferences) {
    const select = root.querySelector('#' + pref.key);
    select.closest('.preference-row').querySelector('.apply').onclick = event => {
      notebook.applyPreference(pref.key, select.value);
      event.target.textContent = 'Applied';
    };
  }
  notebook.subscribe(event => { if (event === 'document') render(); });
  render();
}

